  var steps='<span class="wizard-step is-active"><i>01</i>基本信息</span><span class="wizard-step"><i>02</i>进度与评分</span>'+(hasReviewPage?'<span class="wizard-step"><i>03</i>观后感</span>':'');
  var reviewPage=hasReviewPage?'<section class="form-page"><div class="field-intro">这里写下看完之后留下的感受，之后会显示在番剧详情中。</div><label>观后感</label><textarea id="watch_note" class="watch-note-editor" rows="12" placeholder="写下你对这部作品的感受…">'+esc(w.note||'')+'</textarea></section>':'';
  var pending=pendingMoegirlDraft?'<div class="watch-moegirl-pending"><div><strong>已抓到萌娘百科资料</strong><span>'+esc(pendingMoegirlDraft.sourceTitle||pendingMoegirlDraft.title||'')+'</span></div><div class="watch-confirm-actions"><button class="btn btn-pub" type="button" onclick="confirmMoegirl()">应用资料</button><button class="btn btn-ghost" type="button" onclick="rejectMoegirl()">忽略</button></div></div>':'';
  el.innerHTML=[
    '<div class="watch-editor"><div class="wizard" data-wizard="watchWizard">',
    '<div class="wizard-head"><div class="wizard-steps">'+steps+'</div><span class="wizard-count">1 / '+(hasReviewPage?'3':'2')+'</span></div>',
    '<section class="form-page is-active"><div class="field-intro">先填写作品的基本信息。番名、版本类型、状态和萌娘百科网址必须填写；封面可以留空，稍后再补。</div><div class="watch-basic-layout"><div class="watch-cover-column"><div class="watch-editor-cover" id="watch_editor_cover" onclick="upWatchCover(-1)">'+cover+'</div><button class="btn btn-ghost watch-cover-upload" type="button" onclick="upWatchCover(-1)">上传 / 更换封面</button></div><div class="watch-editor-fields"><div><label>番名</label><input id="watch_title" required value="'+esc(w.title||'')+'" placeholder="例如：新世纪福音战士"></div><div><label>版本类型</label><select id="watch_format"><option value="tv" '+(currentFormat==='tv'?'selected':'')+'>TV版</option><option value="movie" '+(currentFormat==='movie'?'selected':'')+'>剧场版</select></div><div><label>状态</label><select id="watch_status">'+statusOptions+'</select></div><div class="wide"><label>封面地址</label><div class="watch-inline"><input id="watch_cover" value="'+esc(w.cover||'')+'" placeholder="/images/anime/…" oninput="watchCoverPreview()"></div></div><div class="wide"><label>萌娘百科网址</label><div class="watch-inline"><input id="watch_page_url" required value="'+esc(w.pageUrl||'')+'" placeholder="https://zh.moegirl.org.cn/…"><button class="btn btn-ghost" type="button" onclick="fetchMoegirl(-1)">抓取资料</button></div><div class="field-help">填写地址后可抓取封面；应用前会保留你手动输入的番名。</div></div></div></div></section>',
    '<section class="form-page"><div class="field-intro">TV版只在“在追”时填写当前进度；总集数适用于所有 TV版。剧场版不显示集数信息，评分和看完时间只在追完后填写。</div><div class="watch-editor-fields"><div class="watch-episode-row" data-watch-field="episodes"><div class="watch-episode-inputs"><div class="watch-episode-field" data-watch-field="progress"><label for="watch_progress">当前进度</label><input id="watch_progress" value="'+esc(w.progress==null?'':w.progress)+'" placeholder="当前进度" inputmode="numeric"></div><div class="watch-episode-field" data-watch-field="total"><label for="watch_total">总集数</label><input id="watch_total" value="'+esc(w.total==null?'':w.total)+'" placeholder="总集数" inputmode="numeric"></div></div></div><div class="watch-field watch-rating-field" data-watch-field="rating"><label>评分</label><div class="watch-rating-control"><input id="watch_rating" type="range" min="0" max="10" step="0.1" value="'+ratingValue+'" data-empty="'+(ratingText?'false':'true')+'" aria-label="评分"><output id="watch_rating_value">'+(ratingText?Number(ratingValue).toFixed(1)+' 分':'未评分')+'</output><button type="button" class="watch-rating-clear" onclick="clearWatchRating()">清除</button></div></div><div class="watch-field" data-watch-field="finished-at"><label>看完时间</label><input id="watch_finished_at" value="'+esc(w.finishedAt||w.completedAt||'')+'" type="text" class="admin-date-input" placeholder="YYYY-MM-DD"></div></div></section>',
    reviewPage,
    '<div class="wizard-nav"><button type="button" class="btn btn-ghost wizard-prev" data-wizard-delta="-1">上一步</button><button type="button" class="btn btn-ghost wizard-next" data-wizard-delta="1">下一步</button></div></div></div>',pending
  ].join('');
  wizardInit('watchWizard');
  enhanceSelects(el);
  enhanceDateInputs(el);
  var formatInput=document.getElementById('watch_format'),statusInput=document.getElementById('watch_status');
  if(formatInput)formatInput.addEventListener('change',function(){watchEditorData=collectWatchEditor();watchEditorData.format=formatInput.value;renderWatchEditor()});
  if(statusInput)statusInput.addEventListener('change',function(){watchEditorData=collectWatchEditor();watchEditorData.status=statusInput.value;renderWatchEditor()});
  var ratingInput=document.getElementById('watch_rating');if(ratingInput)ratingInput.addEventListener('input',function(){ratingInput.dataset.empty='false';syncWatchRating()});
