function newWatch(status){watchEditorIdx=-1;watchEditorDraftIdx=-1;watchEditorIsDraft=true;watchEditorData=watchDraft();watchEditorData.status=status||'watching';pendingMoegirlDraft=null;moegirlAutoUrl='';document.getElementById('watch_mode').textContent='添加番剧';document.getElementById('watchModalStatus').textContent='';wizardReset('watchWizard');renderWatchEditor();wizardReset('watchWizard');openAdminModal('watchModal')}
function watchEdit(i){if(!watching[i])return;watchEditorIdx=i;watchEditorDraftIdx=-1;watchEditorIsDraft=false;watchEditorData=Object.assign(watchDraft(),watching[i]);pendingMoegirlDraft=null;moegirlAutoUrl='';document.getElementById('watch_mode').textContent='编辑番剧';document.getElementById('watchModalStatus').textContent='';wizardReset('watchWizard');renderWatchEditor();wizardReset('watchWizard');openAdminModal('watchModal')}
