function collectWatchEditor(){var w=Object.assign(watchDraft(),watchEditorData||{});function v(id){var el=document.getElementById(id);return el?el.value.trim():''}w.title=v('watch_title');w.format=v('watch_format')||watchFormat(w);w.status=v('watch_status')||'watching';w.progress=v('watch_progress');w.total=v('watch_total');var rating=document.getElementById('watch_rating');w.rating=rating&&rating.dataset.empty!=='true'?rating.value:'';w.finishedAt=v('watch_finished_at');w.note=w.status==='finished'?v('watch_note'):'';w.cover=v('watch_cover');w.pageUrl=v('watch_page_url');return w}
