async function saveWatchDraft(){var w=collectWatchEditor();if(!w.title&&!w.pageUrl&&!w.cover&&!w.note){show('watchModalStatus','请至少填写番名、萌娘地址、封面或观后感中的一项',false);return}w.id=(watchEditorDraftIdx>=0&&watchDrafts[watchEditorDraftIdx]&&watchDrafts[watchEditorDraftIdx].id)||('watch-draft-'+Date.now().toString(36));w.savedAt=nowStr();if(watchEditorDraftIdx>=0)watchDrafts[watchEditorDraftIdx]=w;else{watchDrafts.unshift(w);watchEditorDraftIdx=0}await saveWatchDrafts();renderWatch();closeAdminModal('watchModal');show('watchStatus','草稿已保存到草稿箱',true)}
async function saveWatchEditor(){if(!validateWatchAll())return;var w=collectWatchEditor(),draftIndex=watchEditorDraftIdx;watchEditorData=w;if(w.status==='finished'&&!w.finishedAt)w.finishedAt=new Date().toISOString().slice(0,10);if(watchEditorIdx<0)watching.push(w);else watching[watchEditorIdx]=w;pendingMoegirlDraft=null;await api('/api/watching',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({watching:watching})});if(draftIndex>=0){watchDrafts.splice(draftIndex,1);await saveWatchDrafts()}watchEditorDraftIdx=-1;watchEditorIsDraft=false;renderWatch();closeAdminModal('watchModal');show('watchStatus','已保存番剧',true);syncToGit()}
