var dynamics=[],editDynIdx=-1;
async function loadDyn(){var d=await api('/api/dynamics');dynamics=d.dynamics||[];renderDyn();resetDyn()}
function renderDyn(){var el=document.getElementById('dynlist');el.innerHTML=dynamics.map(function(d,i){return '<div class="dynrow"><div class="dynrow-main"><div class="dynrow-text">'+esc(d.text||'')+'</div><div class="dynrow-meta">'+esc(d.date||'')+(d.image?' · <span class="dynrow-imgtag">有图</span>':'')+'</div></div><div style="display:flex;gap:6px;align-items:center;flex-shrink:0"><button class="btn btn-ghost" onclick="editDyn('+i+')">编辑</button><button class="btn btn-del" onclick="delDyn('+i+')">删除</button></div></div>'}).join('')||'<div class="small" style="padding:8px 0">还没有动态</div>'}
function dtStr(){var d=new Date();function p(n){return (n<10?'0':'')+n}return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())}function resetDyn(){editDynIdx=-1;document.getElementById('dyn_text').value='';document.getElementById('dyn_img').value='';document.getElementById('dyn_edit_time').value='';document.getElementById('dyn_publish_time').textContent='新动态将使用系统时间';var file=document.getElementById('dyn_img_files');if(file)file.value='';var fileLabel=document.getElementById('dyn_img_files_name');if(fileLabel)fileLabel.textContent='尚未选择图片';document.getElementById('dyn_image_preview').innerHTML='';document.getElementById('dyn_mode').textContent='发布新动态';document.getElementById('dyn_pubbtn').textContent='发布';wizardReset('dynWizard')}
function newDyn(){resetDyn();openAdminModal('dynModal')}
function cancelDyn(){resetDyn();closeAdminModal('dynModal')}
function editDyn(i){editDynIdx=i;var d=dynamics[i];document.getElementById('dyn_text').value=d.text||'';document.getElementById('dyn_img').value=d.image||'';document.getElementById('dyn_edit_time').value=d.editedAt||d.updated||'';document.getElementById('dyn_publish_time').textContent=d.publishedAt||d.createdAt||d.date||'系统时间';document.getElementById('dyn_mode').textContent='编辑动态';document.getElementById('dyn_pubbtn').textContent='更新';wizardReset('dynWizard');openAdminModal('dynModal')}
async function shiftPinnedDynamics(startIndex,delta){var d=await api('/api/pinned');var pinned=(d.pinned||[]).map(function(it){if(it.type==='dynamic'&&Number(it.index)>=startIndex)return {type:'dynamic',index:Number(it.index)+delta};return it});await api('/api/pinned',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pinned:pinned})})}
async function removePinnedDynamic(index){var d=await api('/api/pinned');var pinned=(d.pinned||[]).filter(function(it){return !(it.type==='dynamic'&&Number(it.index)===index)}).map(function(it){if(it.type==='dynamic'&&Number(it.index)>index)return {type:'dynamic',index:Number(it.index)-1};return it});await api('/api/pinned',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pinned:pinned})})}
async function publishDyn(){var text=document.getElementById('dyn_text').value.trim();if(!text){show('dynStatus','请输入内容',false);return}var now=dtStr(),isNew=editDynIdx<0,editTime=document.getElementById('dyn_edit_time').value.trim(),entry={text:text,image:document.getElementById('dyn_img').value.trim(),date:isNew?now:(dynamics[editDynIdx].date||now),editedAt:editTime||now};if(isNew){entry.publishedAt=now;dynamics.unshift(entry)}else{entry.publishedAt=dynamics[editDynIdx].publishedAt||dynamics[editDynIdx].date||now;dynamics[editDynIdx]=Object.assign(dynamics[editDynIdx],entry)}await saveDyn(false);if(isNew)await shiftPinnedDynamics(0,1);await syncToGit();closeAdminModal('dynModal');resetDyn()}
function upDynCompose(){var input=document.getElementById('dyn_img_files');var files=Array.from(input&&input.files||[]);var label=document.getElementById('dyn_img_files_name');if(label)label.textContent=files.length?(files.length+' 张图片'):'尚未选择图片';if(!files.length)return;Promise.all(files.map(function(f){return compressImage(f).then(function(data){return api('/api/img',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:f.name,album:'dynamics',data:data})})})})).then(function(items){var srcs=items.map(function(d){return d.src}).filter(Boolean);document.getElementById('dyn_img').value=srcs.join('|');var preview=document.getElementById('dyn_image_preview');if(preview)preview.innerHTML=srcs.map(function(src){return '<img src="'+esc(src)+'" alt="">'}).join('')})}
async function saveDyn(publish){await api('/api/dynamics',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dynamics:dynamics})});show('dynStatus','已保存动态',true);renderDyn();if(publish!==false)await syncToGit()}
async function delDyn(i){if(!confirm('删除这条动态？'))return;dynamics.splice(i,1);await saveDyn(false);await removePinnedDynamic(i);await syncToGit()}

