function fmtSize(b){b=+b||0;if(b<1024)return b+' B';if(b<1048576)return (b/1024).toFixed(1)+' KB';return (b/1048576).toFixed(2)+' MB'}
function parseExif(buf){var out={};if(!buf||buf.length<4||buf[0]!==0xFF||buf[1]!==0xD8)return out;function u16(o){return (buf[o]<<8)|buf[o+1]}var off=2,tiff=0;while(off+4<buf.length){if(buf[off]!==0xFF){off++;continue}var mar=buf[off+1];var size=u16(off+2);if(mar===0xE1){var sig='';for(var k=0;k<6;k++)sig+=String.fromCharCode(buf[off+4+k]);if(sig==='Exif\0\0'){tiff=off+10;break}}off+=2+size}if(!tiff)return out;var endian=buf.readUInt16BE(tiff);var t=endian===0x4D49?buf.readUInt16LE.bind(buf):buf.readUInt16BE.bind(buf);var t32=endian===0x4D49?buf.readUInt32LE.bind(buf):buf.readUInt32BE.bind(buf);if(endian!==0x4D49&&endian!==0x4949)return out;var ifd0=tiff+t(tiff+2);function rd(dpos,cnt){var s='';for(var j=0;j<cnt;j++)s+=String.fromCharCode(buf[dpos+j]);return s.replace(/\0+$/,'').trim()}function rn(typ,dpos,cnt){return typ===5?(t32(dpos)/t32(dpos+4)).toFixed(1):t(dpos)}function rt(typ,dpos,cnt){if(typ===5){var s2=t32(dpos),d2=t32(dpos+4);if(s2>0&&d2>0){if(s2>=d2)return (s2/d2).toFixed(1)+'s';else return '1/'+Math.round(d2/s2)+'s'}}return t(dpos)}function rtag(ifd){var n=t(ifd),i;for(i=0;i<n;i++){var e=ifd+2+i*12;var tag=t(e),type=t(e+2),cnt=t32(e+4);var valOff=e+8;var bytes=type===1?1:(type===3?2:(type===4?4:type===5?8:type===7?1:4));var size=bytes*cnt;var dp=(size<=4)?valOff:tiff+t32(valOff);if(tag===0x010F)out.Make=rd(dp,cnt);else if(tag===0x0110)out.Model=rd(dp,cnt);else if(tag===0x829D)out.FNumber=rn(type,dp,cnt);else if(tag===0x829A)out.ExposureTime=rt(type,dp,cnt);else if(tag===0x8827)out.ISO=t32(dp);else if(tag===0x920A)out.FocalLength=rn(type,dp,cnt);else if(tag===0xA405)out.FocalLength35=t(dp);else if(tag===0x9209)out.Flash=t(dp);else if(tag===0x9003)out.DateTimeOriginal=rd(dp,cnt);else if(tag===0x8769){var exifIfd=tiff+t32(dp);rtag(exifIfd)}}}rtag(ifd0);return out}
function toNum(s){if(s==null)return NaN;var p=String(s).trim().split('/');if(p.length===2){var n=+p[0],d=+p[1];return d?n/d:NaN}return +p[0]}
function flashStrS(v){v=+v;if(isNaN(v))return '';if(v&1)return '闪光';if(v===0)return '无闪光';if(v===16||v===24)return '未闪光(自动)';if(v===25||v===7)return '闪光(自动)';return (v&1)?'闪光':'未闪光'}
function fmtExifS(ex){if(!ex)return {};var o={};['Make','Model','ISO','DateTimeOriginal'].forEach(function(k){if(ex[k])o[k]=ex[k]});if(ex.FNumber){var fn=toNum(ex.FNumber);if(!isNaN(fn))o.FNumber='f/'+(fn%1?fn.toFixed(1):fn)}if(ex.ExposureTime){var et=String(ex.ExposureTime).trim(),pp=et.split('/');if(pp.length===2){var n=+pp[0],d=+pp[1];if(d&&n>0&&n<d)o.ExposureTime='1/'+Math.round(d/n)+'s';else o.ExposureTime=(n/d).toFixed(1)+'s'}else{var v=+et;if(v>0&&v<1)o.ExposureTime='1/'+Math.round(1/v)+'s';else o.ExposureTime=(v|0)+'s'}}if(ex.FocalLength35){var f35=toNum(ex.FocalLength35);o.FocalLength=((!isNaN(f35))?f35:ex.FocalLength35)+'mm'}else if(ex.FocalLength){var fl=toNum(ex.FocalLength);o.FocalLength=((!isNaN(fl))?fl:ex.FocalLength)+'mm'}if(ex.Flash){var fs=flashStrS(ex.Flash);if(fs)o.Flash=fs}return o}function openImgDetail(src){var lb=document.getElementById('imgdetail'),im=document.getElementById('imgDetailImg');if(!lb||!im)return;lb.classList.add('show');im.src=src;document.body.style.overflow='hidden';document.body.style.paddingRight=(window.innerWidth-document.documentElement.clientWidth)+'px';var info=document.getElementById('imgDetailInfo');info.innerHTML='<div class="imgdetail-loading">读取图片信息…</div>';var tmp=new Image();tmp.onload=function(){var dims=tmp.naturalWidth+' × '+tmp.naturalHeight;fetch(src).then(function(r){return r.arrayBuffer()}).then(function(buf){var ex=parseExif(buf);var size=buf.byteLength;var rows='<div class="imgdetail-rows">';rows+=row('分辨率',dims);rows+=row('文件大小',fmtSize(size));if(ex.DateTimeOriginal)rows+=row('拍摄时间',ex.DateTimeOriginal);rows+='</div>';var fe=fmtExifS(ex);var exr='';['Make','Model','FNumber','ExposureTime','ISO','FocalLength','Flash'].forEach(function(k){if(fe[k])exr+=row({Make:'厂商',Model:'拍摄机型',FNumber:'光圈',ExposureTime:'快门',ISO:'ISO',FocalLength:'焦距',Flash:'闪光灯'}[k],fe[k])});if(fe.DateTimeOriginal)exr+=row('拍摄时间',fe.DateTimeOriginal);info.innerHTML=rows+(exr?'<div class="imgdetail-sub">EXIF</div><div class="imgdetail-rows">'+exr+'</div>':'')}).catch(function(){info.innerHTML='<div class="imgdetail-rows">'+row('分辨率',dims)+'</div>'})};tmp.src=src;function row(k,v){return '<div class="imgdetail-row"><span class="k">'+k+'</span><span class="v">'+v+'</span></div>'}}
function closeImgDetail(){var lb=document.getElementById('imgdetail');if(lb)lb.classList.remove('show');document.body.style.overflow='';document.body.style.paddingRight=''}
document.getElementById('albums').addEventListener('click',function(e){var t=e.target.closest('.imgcard-thumb');if(t&&t.dataset.src){openImgDetail(t.dataset.src)}});/* ---- 友链 ---- */
